// Test fixtures: `.crate` files and Cargo.lock files built in memory, so the
// tests need no system `tar` and can build archives no packager would.

import { createHash } from 'node:crypto';
import { gzipSync } from 'node:zlib';

import { tar } from '../lib/testing.mjs';

export function sha256Hex(bytes) {
  return createHash('sha256').update(bytes).digest('hex');
}

/**
 * A `.crate` file for `name` `version` holding `files` (path → contents,
 * under `<name>-<version>/`), and its Cargo.lock entry.
 */
export function crateFile(name, version, files = { 'Cargo.toml': `[package]\nname = "${name}"\nversion = "${version}"\n` }) {
  const root = `${name}-${version}`;
  const bytes = gzipSync(tar(Object.entries(files).map(([p, data]) => ({ path: `${root}/${p}`, data }))));
  return { name, version, checksum: sha256Hex(bytes), bytes };
}

/** A Cargo.lock (version 4) pinning `crates` from crates.io, and anything in `extra`. */
export function lockfile(crates, extra = '') {
  const blocks = crates.map(
    (c) =>
      `[[package]]\nname = "${c.name}"\nversion = "${c.version}"\n` +
      `source = "registry+https://github.com/rust-lang/crates.io-index"\nchecksum = "${c.checksum}"\n`,
  );
  return `# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\nversion = 4\n\n${[...blocks, extra].join('\n')}`;
}
